var Distributor = class {
  atomic;
  electronicDiagram;
  constructor(atomic) {
    this.atomic = atomic;
    this.buildElectronicDiagram();
    this.distributeElectrons();
  }
  // Cria uma matriz 2D não-linear seguindo o princípio de Aufbau
  buildElectronicDiagram() {
    this.electronicDiagram = new Array(7).fill(0).map((_, x) => {
      const length = 4.5 - Math.abs(x - 3.5);
      return new Array(Math.floor(length)).fill(0);
    });
  }
  distributeElectrons() {
    let electrons = this.atomic;
    let layer = 0;
    let sublevel = 0;
    while (electrons > 0) {
      let x = layer;
      let y = sublevel;
      for (; y >= 0 && x <= 6; x++, y--) {
        const maxDecay = 2 + 4 * y;
        const decay = Math.min(electrons, maxDecay);
        this.electronicDiagram[x][y] = decay;
        electrons -= decay;
      }
      if (layer === sublevel)
        layer++;
      else
        sublevel++;
    }
  }
  // Retorna o total de elétrons em cada camada
  get shells() {
    return this.electronicDiagram.map((layer) => layer.reduce((a2, b) => a2 + b, 0));
  }
};

